import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"18、【蠱】 巽下艮上","description":"周易尚氏學 - 18、【蠱】 巽下艮上","frontmatter":{"title":"18、【蠱】 巽下艮上","description":"周易尚氏學 - 18、【蠱】 巽下艮上"},"headers":[],"relativePath":"classics/shangshi/023.md","filePath":"classics/shangshi/023.md"}'),s={name:"classics/shangshi/023.md"};function t(h,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_18、【蠱】-巽下艮上" tabindex="-1">18、【蠱】 巽下艮上 <a class="header-anchor" href="#_18、【蠱】-巽下艮上" aria-label="Permalink to “18、【蠱】 巽下艮上”">​</a></h1><p>左傳蟲蠱。而歸藏作蜀。《詩》曰：蜎蜎者蠋；蠋，葵中蠶也。詩詁蜀已有蟲。再加蟲俗字。然則蜀亦蟲。與蠱義同也。蠱敗也。壞也。卦上山震木。為材木之所出。乃下卦為巽。巽隕落故敗。又巽為蟲。蟲蠢物朽腐。大過曰棟撓。易林旅之履雲。木內生蠢。蠢即蠱。皆以巽也。故壞。禮王制。執左道以亂政疏雲。蠢者損壞之名。周禮秋官庶氏。掌除毒蠱。鄭注毒蠱蟲物而病害人者。又翦氏。掌除蠢物。凡庶蠱之事。注蠱。蠢之類。又史記秦德公二年初伏。以狗御蠱。注蠱惡氣。是蠱之為蠢為腐壞甚明。又左傳雲。女惑男。風落山。謂之蠱。女惑男。男敗。風落山。山敗。亦以敗壞說蠱。荀爽謂蠱為事。朱子蓋以為不安。又曰壞極而有事。夫卦名皆由卦象而生。詁蠱為事為惑。皆正訓不誤。而此則義為敗壞。亦卦象所命也。彖曰巽而止蠱。亦以敗壞為說。若必拘序卦而訓為事。則此句義難通矣。陽得陰則通。坤為大川。為事。剛往坤上。下履重陰。容民得眾。故曰利涉大川。曰往有事。乾元為甲、蠱之先為泰。乾為日。三爻故曰先甲三日。乃由泰反否而蠱為之始。初交上為蠱。二三隨上成否。甲之在下者反上。先甲變為後甲矣。故又曰後甲三日。蠱旁通隨。隨者由否反泰之始。上爻下成隨。四五隨下成泰。甲之在上者反下。後甲又變為先甲矣。否泰相循環相終始。來往　信。天道因如是也。</p><p>彖曰。蠱剛上而柔下。巽而止蠱。蠱元亨而天下治也。利涉大川。往有事也。先甲三日。後甲三日。終則有始。天行也。</p><p>行道也。泰者隨之終。蠱者否之始。故曰終則有始。</p><p>象曰。山下有風。蠱。君子以振民育德。</p><p>風止山下。氣鬱不通。故蠱。蠱則不生育。振而作之。所以救蠱而育德也。象義有因卦象而取法者。有反省者。茲則反省者也。</p><p>初六。於父之蠱。有子考。無咎。厲終吉。</p><p>初雖不當位。然上承重陽。與上合志。與升初六同。故吉。易林以震巽為父母。詳焦氏易詁朱漢上以復姤為小父母。復殷（左艮）仍震巽。初伏震。故曰父。曰了。乾正也。能正父蠱。故曰有子考。逸周書謐法雲。考成也。左氏襄十三年彌廟疏。考成也。言有成德也。有子考者。即謂有子能成就先業也。故無咎。風隕故厲。承陽故終吉。馬融王肅讀考字絕句。王注作考無咎。非也。</p><h3 id="象曰。乾父之蠱。意承考也。" tabindex="-1">象曰。乾父之蠱。意承考也。 <a class="header-anchor" href="#象曰。乾父之蠱。意承考也。" aria-label="Permalink to “象曰。乾父之蠱。意承考也。”">​</a></h3><p>意承考。謂初上承重陽。能承繼先德也。承順也。巽象。</p><p>九二：幹母之蠱，不可貞。</p><h3 id="象曰。幹母之蠱。得中道也。" tabindex="-1">象曰。幹母之蠱。得中道也。 <a class="header-anchor" href="#象曰。幹母之蠱。得中道也。" aria-label="Permalink to “象曰。幹母之蠱。得中道也。”">​</a></h3><p>二五得中。</p><p>九三。乾父之蠱。小有悔。無大咎。</p><p>三震體。故亦因父。按九三上雖無應。然當位。前臨重陰。與大畜九三象同。當吉。乃大畜九三利往。此雲小悔無大咎者。以體下斷也。凡巽體上交多不吉。先儒不知其故在本弱。故多誤解。</p><h3 id="象曰。乾父之蠱。終無咎也。" tabindex="-1">象曰。乾父之蠱。終無咎也。 <a class="header-anchor" href="#象曰。乾父之蠱。終無咎也。" aria-label="Permalink to “象曰。乾父之蠱。終無咎也。”">​</a></h3><p>九三前臨重陰。利往。故終無咎。</p><p>六四。裕父之蠱。往見吝。</p><p>裕寬也。虞雲不能淨父過也。前遇敵。陰遇陰則窒。故往吝。</p><h3 id="象曰。裕父之蠱。往未得也。" tabindex="-1">象曰。裕父之蠱。往未得也。 <a class="header-anchor" href="#象曰。裕父之蠱。往未得也。" aria-label="Permalink to “象曰。裕父之蠱。往未得也。”">​</a></h3><p>六五。幹父之蠱。用譽。</p><p>得中。有應。上承陽。而艮為名。故可致聞譽。</p><h3 id="象曰。乾父用譽。承以德也。" tabindex="-1">象曰。乾父用譽。承以德也。 <a class="header-anchor" href="#象曰。乾父用譽。承以德也。" aria-label="Permalink to “象曰。乾父用譽。承以德也。”">​</a></h3><p>德謂陽。承以德。言上承陽也。</p><p>上九。不事王侯。高尚其事。</p><p>三震為王。為諸侯。上不應之。故曰不事王侯。言不事王侯之事也。高居物表。逍遙事外。故曰高尚其事。</p><h3 id="象曰。不事王侯。志可則也。" tabindex="-1">象曰。不事王侯。志可則也。 <a class="header-anchor" href="#象曰。不事王侯。志可則也。" aria-label="Permalink to “象曰。不事王侯。志可則也。”">​</a></h3><p>則法也。不事王侯。若共伯和吳季禮之流是也。作奉事者非。</p>',28)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
